-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('stats-bar-chart', 'stats-pie-chart', 'stats-dotplot', 'stats-histogram', 'stats-stem-leaf', 'stats-boxplot', 'stats-two-cat-side-by-side', 'stats-two-cat-segmented', 'stats-two-cat-mosaic') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('stats-bar-chart', 'stats-pie-chart', 'stats-dotplot', 'stats-histogram', 'stats-stem-leaf', 'stats-boxplot', 'stats-two-cat-side-by-side', 'stats-two-cat-segmented', 'stats-two-cat-mosaic');
  if v_n <> 9 then
    raise exception 'expected 9 figures, found %', v_n;
  end if;
end $$;

commit;
